const beaconHalo = new THREE.Mesh(new THREE.CylinderGeometry(.08, .5, 4, 8, 1, true), new THREE.MeshBasicMaterial({ color: '#f8d994', transparent: true, opacity: .04, side: THREE.DoubleSide, depthWrite: false }));
beaconHalo.position.set(.5, beaconBaseY + 2.1, -.5); beacon.add(beaconHalo);

