function topAt(x, z) {
  const ix = Math.round(x), iz = Math.round(z);
  let highest = -100;
  for (const b of world.values()) if (b.x === ix && b.z === iz) highest = Math.max(highest, b.y);
  return highest > -100 ? highest + .5 : -30;
}

input.newString:
function topAt(x, z) {
  const ix = Math.round(x), iz = Math.round(z);
  for (let y = 16; y >= -8; y--) if (world.has(keyOf(ix, y, iz))) return y + .5;
  return -30;
}

