393:   if (shard) prompt.innerHTML = `${isTouch ? 'TAP E' : 'E'} <span>Collect sky shard</span>`;
394: }
395: function animate() {
396:   requestAnimationFrame(animate);
397:   const dt = Math.min(clock.getDelta(), .1), time = clock.elapsedTime;
398:   elapsed += dt;
399:   updateDaylight(dt);
400:   updatePlayer(dt);
401:   shards.forEach((s, i) => {
402:     if (s.collected) return;
403:     s.group.position.y = s.baseY + Math.sin(time * 1.7 + i) * .16;
404:     s.crystal.rotation.y = time * .55 + i;
405:     s.ring.rotation.z = time * .35 + i;
406:   });
407:   beaconCore.rotation.y = time * (beaconRestored ? .85 : .3);
408:   beaconRing.rotation.z = time * .16;
409:   beaconHalo.material.opacity = beaconRestored ? .11 + Math.sin(time * 2) * .025 : .035 + Math.sin(time * 1.3) * .012;
410:   clouds.forEach((cloud, i) => { cloud.position.x += dt * (.16 + i * .025); if (cloud.position.x > 27) cloud.position.x = -27; });
411:   islandMist.rotation.y += dt * .008;
412:   ocean.position.x = player.x * .08; ocean.position.z = player.z * .08;
413:   if (toastTimer > 0) { toastTimer -= dt; if (toastTimer <= 0) toast.classList.remove('show'); }
414:   if (sunLight.castShadow) sunLight.position.set(Math.cos(cycle * Math.PI * 2) * 34, Math.max(2, Math.sin(cycle * Math.PI * 2) * 34), -20);
415:   renderer.render(scene, camera);
416: }
